CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY,display_name VARCHAR(80) NOT NULL,avatar_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),last_seen_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rooms(id UUID PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(80) UNIQUE NOT NULL,icon VARCHAR(10) DEFAULT '💬',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,room_id UUID REFERENCES rooms(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,content TEXT NOT NULL CHECK(char_length(content)<=5000),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_messages_room_created ON messages(room_id,created_at DESC);
